// Optional brand artwork: if public/brand/<name>.png exists (for example an
// illustration generated by the owner), show it; otherwise render the fallback
// so the page never shows a broken image. A failure is remembered per URL, so
// changing the name tries again.

import { useState, type ReactNode } from "react";

export function BrandImage({ name, alt, fallback, width, height, className }: { name: string; alt: string; fallback: ReactNode; width?: number | string; height?: number | string; className?: string }) {
  const src = "/brand/" + name + ".png";
  const [failedSrc, setFailedSrc] = useState<string | null>(null);
  if (failedSrc === src) return <>{fallback}</>;
  return <img src={src} alt={alt} width={width} height={height} className={className} loading="lazy" onError={() => setFailedSrc(src)} style={{ maxWidth: "100%", height: "auto" }} />;
}
